package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Integer;
    in attribute io_1_valid : Boolean;
    attribute buzzActive : Boolean := false;
    attribute buzzElapsedMs : Integer := 0;
    perform action tick {
      first start;
      then if io_1_valid and io_1 == 1 {
        first start;
        then assign buzzActive := true;
        then assign buzzElapsedMs := 0;
      }
      then if buzzActive {
        first start;
        then assign buzzElapsedMs := buzzElapsedMs;
        then if buzzElapsedMs >= 500 {
          first start;
          then assign buzzActive := false;
        }
      }
    }
    out attribute io_0 : Integer = (if buzzActive ? 500 else 0);
  }
  part system : Controller;
}
